export const CHAPTER_FILES = {"15":{"die.py":"from random import randint\n\nclass Die:\n    \"\"\"A class representing a single die.\"\"\"\n\n    def __init__(self, num_sides=6):\n        \"\"\"Assume a six-sided die.\"\"\"\n        self.num_sides = num_sides\n\n    def roll(self):\n        \"\"\"\"Return a random value between 1 and number of sides.\"\"\"\n        return randint(1, self.num_sides)","random_walk.py":"from random import choice\n\n\nclass RandomWalk:\n    \"\"\"A class to generate random walks.\"\"\"\n\n    def __init__(self, num_points=5000):\n        \"\"\"Initialize attributes of a walk.\"\"\"\n        self.num_points = num_points\n\n        # All walks start at (0, 0).\n        self.x_values = [0]\n        self.y_values = [0]\n\n    def fill_walk(self):\n        \"\"\"Calculate all the points in the walk.\"\"\"\n        # Keep taking steps until the walk reaches the desired length.\n        while len(self.x_values) < self.num_points:\n\n            # Decide which direction to go, and how far to go.\n            x_direction = choice([1, -1])\n            x_distance = choice([0, 1, 2, 3, 4])\n            x_step = x_direction * x_distance\n\n            y_direction = choice([1, -1])\n            y_distance = choice([0, 1, 2, 3, 4])\n            y_step = y_direction * y_distance\n\n            # Reject moves that go nowhere.\n            if x_step == 0 and y_step == 0:\n                continue\n\n            # Calculate the new position.\n            x = self.x_values[-1] + x_step\n            y = self.y_values[-1] + y_step\n\n            self.x_values.append(x)\n            self.y_values.append(y)","random_walk_refactored.py":"from random import choice\n\n\nclass RandomWalk:\n    \"\"\"A class to generate random walks.\"\"\"\n\n    def __init__(self, num_points=5000):\n        \"\"\"Initialize attributes of a walk.\"\"\"\n        self.num_points = num_points\n\n        # All walks start at (0, 0).\n        self.x_values = [0]\n        self.y_values = [0]\n\n    def fill_walk(self):\n        \"\"\"Calculate all the points in the walk.\"\"\"\n        # Keep taking steps until the walk reaches the desired length.\n        while len(self.x_values) < self.num_points:\n\n            # Decide which direction to go, and how far to go.\n            x_step = self.get_step()\n            y_step = self.get_step()\n\n            # Reject moves that go nowhere.\n            if x_step == 0 and y_step == 0:\n                continue\n\n            # Calculate the new position.\n            x = self.x_values[-1] + x_step\n            y = self.y_values[-1] + y_step\n\n            self.x_values.append(x)\n            self.y_values.append(y)\n\n    def get_step(self):\n        \"\"\"Calculate a single step in the walk.\"\"\"\n        direction = choice([1, -1])\n        distance = choice([0, 1, 2, 3, 4])\n        step = direction * distance\n\n        return step"}};
